/**
 * Typed clients for the Nova API.
 *
 * `schema.d.ts` is generated from `openapi.yaml` (`pnpm --filter api-types generate`);
 * `openapi.yaml` is generated by the API (`pnpm --filter api-types schema`). Do not edit
 * either by hand.
 */
import createClient, { type ClientOptions, type Middleware } from "openapi-fetch";

import type { components, operations, paths } from "./schema";

export type { components, operations, paths };

/** Every named schema component, e.g. `Schemas["Site"]`. */
export type Schemas = components["schemas"];

export type NovaClient = ReturnType<typeof createClient<paths>>;

const UNSAFE_METHODS = new Set(["POST", "PUT", "PATCH", "DELETE"]);

/** Reads Django's CSRF cookie in a browser; returns undefined elsewhere. */
export function readCsrfCookie(name = "csrftoken"): string | undefined {
  if (typeof document === "undefined") return undefined;
  const prefix = `${name}=`;
  const cookie = document.cookie.split("; ").find((part) => part.startsWith(prefix));
  return cookie ? decodeURIComponent(cookie.slice(prefix.length)) : undefined;
}

/** Sends `X-CSRFToken` on unsafe methods, as the API's session auth requires. */
export function csrfMiddleware(getToken: () => string | undefined = readCsrfCookie): Middleware {
  return {
    onRequest({ request }) {
      if (UNSAFE_METHODS.has(request.method.toUpperCase())) {
        const token = getToken();
        if (token) request.headers.set("X-CSRFToken", token);
      }
      return request;
    },
  };
}

export interface ManagementClientOptions extends Omit<ClientOptions, "baseUrl"> {
  /** API origin, e.g. "https://api.example.com". */
  baseUrl: string;
  /** Override how the CSRF token is read (defaults to the `csrftoken` cookie). */
  getCsrfToken?: () => string | undefined;
}

/**
 * Client for the management API (`/api/manage/…`) and allauth, used by the admin app.
 * Authenticates with the session cookie (`credentials: "include"`) and sends the CSRF token
 * on writes. No token is ever kept in browser storage.
 */
export function createManagementClient({
  getCsrfToken,
  ...options
}: ManagementClientOptions): NovaClient {
  const client = createClient<paths>({ credentials: "include", ...options });
  client.use(csrfMiddleware(getCsrfToken));
  return client;
}

export interface DeliveryClientOptions extends Omit<ClientOptions, "baseUrl" | "headers"> {
  baseUrl: string;
  /** A `nova_dlv_…` or `nova_prv_…` API token. Server-side only: never ship it to a browser. */
  token: string;
}

/** Client for the delivery API (`/api/v1/…`), authenticated with a site's bearer token. */
export function createDeliveryClient({ token, ...options }: DeliveryClientOptions): NovaClient {
  return createClient<paths>({
    credentials: "omit",
    ...options,
    headers: { Authorization: `Bearer ${token}` },
  });
}
